F('engEnd', r"""function engEnd(M,m){const A=M.t.a,B=M.t.b;if(M.done)return;
 if(M.sa===M.sb&&!M.extra){M.extra=true;M.end=M.knockout?110:90;engSay(M,m,'ft',null,'Full time — level after 80 minutes. Golden point extra time!');return}
 if(M.extra&&M.sa===M.sb&&M.knockout){const ka=kickerOf(A),kb=kickerOf(B),pa=1/(1+Math.exp(-(M.mu.diff/10+((ka?traits(ka).kicking:60)-(kb?traits(kb).kicking:60))/25))),W=Math.random()<pa?A:B,k=kickerOf(W),text=`Golden point: ${k?k.name:displayTeam(W.team)} lands the field goal that wins it.`;if(W===A){M.sa+=1;M.pa++}else{M.sb+=1;M.pb++}addPts(M,k?.id,1);M.events.push({minute:m,team:W.team,text,points:1,...(k?{p:k.id}:{})});engSay(M,m,'pen',W,text,{points:1})}
 engSay(M,m,'ft',null,M.extra?(M.sa===M.sb?'Full time after golden point: the points are shared.':'Full time after golden point.'):'Full time.');M.done=true}""")

F('matchStatsCompact', r"""function matchStatsCompact(M){const row=X=>{const t=X.st,n=Math.max(1,M.min),sets=Math.max(t.scN,1),done=clamp(sets-Math.round(t.err*.75),0,sets);return [Math.round(t.poss/n*100),Math.round(t.terr/n*100),t.tk,t.mtk,t.lb,t.to,t.err,t.pc,done,sets,t.loW,t.loN,t.kicks,t.off,t.fdo||0]};return {a:row(M.t.a),b:row(M.t.b)}}""")
